// @returns BOOL in EAX (1/0 on both cookie-checked exits)
// Randomly selects and applies a superior-quality mod row from QualityItems.txt to pUnit. Limits the table to 4 entries for throwable or no-durability items. Uses the item's own seed in a rejection-sampling loop (tracks visited slots in aVisitedSlots[12]) to find a row that passes ITEMMOD_MatchesRepairType, then writes the file index, applies rune/gem stats via ApplyRuneAndGemStats, and calls StaffMod(pUnit, pItemGenContext). Protected by a stack-guard cookie.
static BOOL __thiscall ITEMMOD_GenerateQualityItem(D2UnitStrc * pUnit, D2ItemGenContextStrc * pItemGenContext) {
    D2SeedStrc DVar1;
    int32_t iVar2;
    D2SeedStrc* pDVar7;
    D2MagicAffixTxt* pMagicAffixLine;
    uint32_t nClassId;
    int iVisitedIdx;
    DWORD nRandIdx;
    uint32_t nTableSize;
    char aVisitedSlots[12];
    D2QualityItemsTableStrc* pQualityItemsTableInfo = D2Common::DATATBLS::ItemTbls::TXT_QualityItems_GetTableInfo();
    if (!pUnit) {
      nClassId = -1;
    } else {
      nClassId = pUnit->nClassId;
    }

    D2ItemsTxt* pDVar6 = D2Common::DATATBLS::ItemTbls::TXT_Items_GetLine(nClassId);
    if (pQualityItemsTableInfo && pDVar6) {
      nTableSize = pQualityItemsTableInfo->nSize;
      memset(aVisitedSlots, 0, 10 * sizeof(aVisitedSlots[0]));
      iVar2 = D2Common::ITEMS::Items::ITEM_GetTxtItemTypes_throwable(pUnit);
      if (iVar2 || pDVar6->bNoDurability != '\0') {
        nTableSize = 4;
      }

      while (true) {
        do {
          pDVar7 = D2Common::ITEMS::Items::GetItemSeed(pUnit);
          if ((int)nTableSize <= 0) {
            nRandIdx = 0;
          } else if (nTableSize & nTableSize - 1) {
            DVar1 = D2_SEED_NEXT(*pDVar7);
            pDVar7->nSeedHigh = DVar1.nSeedHigh;
            pDVar7->nSeedLow = DVar1.nSeedLow;
            nRandIdx = (DWORD)(DVar1.nSeedLow % nTableSize);
          } else {
            DVar1 = D2_SEED_NEXT(*pDVar7);
            pDVar7->nSeedHigh = DVar1.nSeedHigh;
            pDVar7->nSeedLow = DVar1.nSeedLow;
            nRandIdx = nTableSize - 1 & DVar1.nSeedLow;
          }
        } while (aVisitedSlots[nRandIdx] != '\0');

        pMagicAffixLine = (D2MagicAffixTxt*)D2Common::DATATBLS::ItemTbls::TXT_QualityItems_GetLine(nRandIdx);
        if (!pMagicAffixLine) {
          break;
        }

        nClassId = D2Common::ITEMS::ItemMods::ITEMMOD_MatchesRepairType(pUnit, (char*)pMagicAffixLine);
        if (nClassId) {
          D2Common::ITEMS::Items::ITEM_SetItemData_nFileIndex(pUnit, nRandIdx);
          D2Common::ITEMS::ItemMods::ApplyRuneAndGemStats(1, nullptr, pUnit, pMagicAffixLine, 0, 0);
          StaffMod(pUnit, pItemGenContext);
          return 1;
        }

        aVisitedSlots[nRandIdx] = '\x01';
        if ((int)nTableSize <= 0) {
          break;
        }

        iVisitedIdx = 0;
        while (aVisitedSlots[iVisitedIdx] != '\0') {
          iVisitedIdx++;
          if (iVisitedIdx >= (int)nTableSize) {
            return 0;
          }
        }
      }
    }

    return 0;
}

